insert into tasks (id,powertrain_id,title,category,group_name,aliases,live,time_label,difficulty) values ('sway-front','bpy','Front sway bar upgrade','Suspension','sway bar',array['front sway bar','fsb','anti-roll bar','stabilizer bar','subframe']::text[],true,'3–5 hr',4) on conflict (id) do update set title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,title,category,group_name,aliases,live,time_label,difficulty) values ('endlinks','bpy','Sway bar end links','Suspension','sway bar',array['end links','end link','drop link','clunk','rattle','stabilizer link']::text[],true,'45 min',1.5) on conflict (id) do update set title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,title,category,group_name,aliases,live,time_label,difficulty) values ('air-filter-oe','bpy','Engine air filter (stock airbox)','Engine','air intake',array['air filter','airbox','engine cover','intake','paper filter']::text[],true,'20 min',1) on conflict (id) do update set title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,title,category,group_name,aliases,live,time_label,difficulty) values ('intake-aftermarket','bpy','Aftermarket intake install','Engine','air intake',array['cold air intake','cai','carbonio','cts intake','injen','k&n','intake']::text[],false,'1–2 hr',2) on conflict (id) do update set title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('sway-front',$j${"id": "sway-front", "title": "Front sway bar upgrade", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "alsoFits": "2006–09 GTI/Rabbit · 05–10 Jetta · 06–08 A3 8P · Mk6 GTI/Golf (same PQ35 front subframe)", "category": "Suspension", "kind": "upgrade", "variants": {"question": "How far do you want to take it apart?", "hint": "The bar hides behind the subframe, so the subframe has to come down either way. Owners mostly lower it a few inches and unbolt the steering rack from it. Manufacturer instructions drop it further and also disconnect the steering column, ball joints and tie rods.", "options": [{"id": "partial", "label": "Partial lower (owner method)", "when": "Fewer parts touched, tighter to work in. Recommended for a driveway."}, {"id": "full", "label": "Full drop (manufacturer method)", "when": "More room, more disconnecting, steering-column care needed. Best on a lift."}]}, "glance": {"timeFirst": "3–5 hr", "timeRepeat": "2 hr with a lift and a helper", "difficulty": 4, "cost": "$250–450 + alignment", "risk": "Subframe on a jack · single-use stretch bolts · alignment afterwards", "why": "The rear bar changed the car's balance. The front bar is about grip: less roll means the outside front tire stays flatter on the road, so a strut car like this one stops giving away camber mid-corner.", "note": "One vendor calls this 'easy'. Every owner account says three hours, two people, and an alignment. Believe the owners."}, "heroCap": "The bar sits in the channel between the subframe and the steering rack. There is no way to get it out without lowering the subframe.", "lifespan": {"title": "When owners do this", "headline": ["Usually after the rear bar and tires, before or with coilovers"], "earliest": null, "detail": "The stock bar doesn't wear out. Owners add a front bar when they've already done the rear and want the front to stop washing out, or as part of a bigger suspension job while the subframe is already down.", "factors": ["Rear bar already installed", "Coilovers or lowering springs going in", "Track days"], "inspect": ["While the subframe is down: dogbone (pendulum) mount bushing and front control-arm bushings are worth a look"], "confidence": {"level": "community", "n": 5, "note": "Forum consensus on ordering. Which bar is a preference."}}, "should": {"yesIf": ["You've done the rear bar and the front still pushes wide", "You want flatter cornering without harsher ride", "You're already dropping the subframe for something else", "You have a torque wrench that does angle, or a patient helper and a marker"], "codes": [], "notes": ["A stiffer front bar on a front-driver sounds like it should add understeer. In practice it reduces body roll, which keeps the loaded front tire upright, so it usually adds front grip rather than taking it away. Rear bar first, then front, is the order almost everyone lands on.", "This is the most involved job in the app so far. Nothing is dangerous once the car is on stands, but a subframe on a floor jack wants a second person, and the alignment afterwards is not optional."], "confidence": {"level": "high", "n": 6, "note": "Method and rationale agree across the manufacturer guide, four forum DIYs, and a magazine test."}}, "parts": [{"tier": "aftermarket", "name": "Front sway bar kit (bar, poly bushings, brackets, grease)", "pn": "see options below", "note": "Most kits include the stretch bolts you need; check yours", "price": "$250–400", "links": []}, {"tier": "oe", "name": "Subframe & control-arm bolts, M12 (×6)", "pn": "single-use", "note": "Stretch bolts. Every source says replace", "price": "$30–50", "links": []}, {"tier": "oe", "name": "Steering rack bolts, M10 (×4)", "pn": "single-use", "note": "Also stretch bolts", "price": "$15", "links": []}, {"tier": "oe", "name": "Pendulum (dogbone) mount bolts", "pn": "single-use", "note": "Two into the transmission", "price": "$10", "links": []}, {"tier": "oe", "name": "End-link nuts (×2)", "pn": "self-locking", "note": "Replace whenever removed", "price": "$4", "links": []}, {"tier": "oe", "name": "Steering shaft u-joint bolt", "pn": "single-use", "note": "Full-drop method only", "price": "$5", "links": [], "only": ["full"]}], "aftermarket": [{"name": "ECS Tuning 26mm", "note": "Solid, non-adjustable, comes with poly bushings, all stretch bolts and subframe spacer plates. The install PDF is the most complete one available.", "price": "$300", "signal": "Best documented", "links": [{"store": "ECS Tuning install PDF", "url": "https://assets.ecstuning.com/edoc/PDF_9205_Volkswagen_MK5-MK6_ECS_Front_Sway_Bar_Installation.pdf"}]}, {"name": "H&R 26mm", "note": "Tubular, non-adjustable, rubber-lined bushings that need no greasing. The bar the 2008 owner DIYs were written around.", "price": "$250–300", "signal": "Forum favorite", "links": []}, {"name": "034Motorsport adjustable", "note": "Two-hole adjustable, billet brackets. Grassroots Motorsports ran it on the soft setting and set a personal best.", "price": "$350–450", "signal": "Track-leaning pick", "links": []}, {"name": "APR / Hotchkis", "note": "Same bar under two names. Instructions insisted on load on the wheels throughout; owners found that only matters for the end links.", "price": "$300–350", "signal": "Fine, with that caveat", "links": []}], "tools": [{"name": "Floor jack + two stands, plus a second jack (or transmission jack) for the subframe", "note": "A board on the jack pad spreads the load"}, {"name": "Sockets: 13, 16, 17, 18, 21mm · ½\" breaker bar", "note": "The 21mm subframe bolts are very tight"}, {"name": "6mm triple-square or 5mm hex (end links) · T20/T25 Torx (belly pan)"}, {"name": "Torque wrench that reads to 120 Nm, and an angle gauge (or a marker for the +90° turns)"}, {"name": "Pry bar, penetrating oil, wire brush, marker or paint pen for reference marks"}, {"name": "Angle grinder (optional)", "note": "Owners cut the hollow stock bar in two rather than wrestle it out", "only": ["partial"]}], "before": ["Level ground. Stands on the body jack points, never under the subframe you're about to drop.", "Raise both sides of the front together; one side up puts the bar under load.", "Mark the subframe's position on the body with a paint pen before a single bolt comes out. Its outline (the 'footprint') is your only alignment reference.", "Book an alignment for afterwards. Subframe position sets toe and camber; you will not get it back exactly by eye.", "Full-drop method: park with the steering wheel dead straight and keep it there. Rotating the wheel with the column disconnected can damage the airbag clockspring."], "steps": [{"n": 1, "title": "Steering shaft (full drop only)", "only": ["full"], "blocks": [{"t": "text", "b": "Inside the car, remove the two 13mm fasteners on the steering-shaft cover at the pedals and lift it off. Remove the u-joint bolt where the shaft meets the rack and slide the joint up off the rack. It's a single-use bolt."}, {"t": "warn", "b": "From this point until the joint is back on, nobody turns the steering wheel. A rotated clockspring is an airbag light at best."}]}, {"n": 2, "title": "Raise the front, wheels off, belly pan off", "blocks": [{"t": "text", "b": "Loosen the lug bolts (17mm) on the ground, raise both sides, stands under the body. Wheels off. Remove the plastic belly pan or insulation tray (T20/T25) so you can see the subframe."}]}, {"n": 3, "title": "Disconnect the end links from the bar", "blocks": [{"t": "text", "b": "18mm nut on each link at the bar. If the stud spins, hold it with a 6mm triple-square (some links: 5mm hex) and turn the nut. They're often seized: wire-brush the exposed thread, soak with penetrating oil, and work the nut back and forth. Don't heat them; the joint boot won't survive it."}, {"t": "ill", "id": "fsb-endlink", "cap": "Stud held, nut turned. Same technique front and rear."}]}, {"n": 4, "title": "Headlight level sensor (if you have HIDs)", "blocks": [{"t": "text", "b": "Driver's side, above the lower control arm: unplug the sensor and unbolt its arm bracket from the arm (10mm). Note which way the joint points so it goes back the same."}]}, {"n": 5, "title": "Ball joints and tie rods (full drop only)", "only": ["full"], "blocks": [{"t": "text", "b": "Remove the three 16mm ball-joint nuts each side and pull the control arm down off the joint; a pry bar between them if they're corroded together. Remove both outer tie-rod nuts (18mm) and pop the tie rods out of the bearing housings with a separator, or a sharp hammer blow to the housing."}]}, {"n": 6, "title": "Unbolt everything hanging on the subframe", "blocks": [{"t": "text", "b": "Two exhaust hanger bolts at the rear of the subframe (13mm). The four steering-rack bolts (13mm), two per side, where the rack sits on the subframe. The four sway-bar bracket bolts (13mm)."}, {"t": "text", "b": "Pendulum (dogbone) mount: two bolts into the transmission (16mm) and, on the partial method, the two into the subframe (13mm) so the mount comes free.", "only": ["partial"]}, {"t": "text", "b": "Pendulum mount: remove the two bolts into the transmission (16mm).", "only": ["full"]}]}, {"n": 7, "title": "Jack under the subframe, then the big bolts", "caution": true, "blocks": [{"t": "text", "b": "Second jack (with a board) snug under the middle of the subframe. Now the six 18mm/21mm subframe and control-arm bolts: two long ones at the rear, two at the rear control-arm brackets, two forward ones hidden behind the control arms (socket on a 6-inch extension). Loosen the forward pair first; remove them last."}, {"t": "warn", "b": "The subframe is heavy and the jack is the only thing holding it. Have your helper steady it from here on. Never put any part of you under it."}, {"t": "torque", "label": "Subframe & control-arm bolts (M12, on reassembly)", "nm": 70, "c": {"level": "varies", "n": 2, "note": "Manufacturer: 70 Nm + 90°. Owner table: 70 Nm (52 lb-ft) + 45°. Same base value; the angle differs. We show the manufacturer's."}, "note": "+90° turn"}]}, {"n": 8, "title": "Lower the subframe", "blocks": [{"t": "text", "b": "Lower the jack slowly and evenly, about four inches, watching the steering rack: it needs to lift off its dowel pins and come free of the subframe. A screwdriver under the rack helps release the pins. The rack stays connected to the column and just hangs.", "only": ["partial"]}, {"t": "text", "b": "Lower the jack a little at a time. As soon as you can reach it, remove the hidden 10mm bolt holding the steering-rack wiring harness to the rack (driver's side, inside the subframe) and release the harness clip a few inches along. Then lower until the bar is fully exposed, and lift the rack slightly rearward off its dowel pins.", "only": ["full"]}, {"t": "ill", "id": "fsb-drop", "cap": "Subframe on the jack, lowered. The bar comes out over the passenger side of the subframe, forward and down, while the driver's end threads between the subframe and rack."}]}, {"n": 9, "title": "Get the old bar out", "timeSink": true, "blocks": [{"t": "text", "b": "Lift the bar up and over the passenger-side subframe arm, bring it forward and down, and guide the driver's end between the subframe and the rack. Two people, some swearing, several attempts. The bushings snag on the rack; snapping the old brackets off the bar first helps."}, {"t": "note", "b": "Owner shortcut: with the bar still bolted in, cut it in half with a grinder. The stock bar is hollow and goes quickly. Eye protection; you're on your back under sparks. Then each half comes out easily.", "only": ["partial"]}]}, {"n": 10, "title": "Bushings and brackets onto the new bar", "blocks": [{"t": "text", "b": "Grease the inside of poly bushings with the kit's grease (never petroleum grease; never any grease on factory rubber bushings). Slide them on against the stops. Lower brackets under, uppers on top, raised face up, bolt holes outboard. Some kits fit the brackets loosely at this point; others want them fully seated. Follow the kit sheet."}]}, {"n": 11, "title": "Feed the new bar in", "blocks": [{"t": "text", "b": "Reverse of step 9: driver's end between rack and subframe first, then lift the passenger end over. Set the bar in front of the rack. Adjust the rack's position as needed so the bar drops into place."}]}, {"n": 12, "title": "Raise the subframe and start every bolt by hand", "caution": true, "blocks": [{"t": "text", "b": "Raise the jack until the subframe meets the body. Seat the steering rack onto its dowel pins first; if it isn't fully seated you'll end up with a loose rack. Then start, by hand and loosely, in this order: rear control-arm bolts, the four rack bolts, the four sway-bar bracket bolts, forward subframe bolts, then the two long rear subframe bolts. Full-drop: reconnect the harness clip and its 10mm bolt as the subframe comes up.", "only": ["partial", "full"]}, {"t": "text", "b": "Kits that supply subframe spacer plates: they go between the subframe and body at the rear mounts. Fit them whether or not the car had them.", "only": ["partial", "full"]}, {"t": "text", "b": "Now align. Nudge the subframe until every bolt hole lines up with your paint marks and the footprint. Loosen the 'horns' and rear brackets if it won't move; snug bolts fight you. Only when everything lines up do you tighten anything."}, {"t": "warn", "b": "Tighten nothing to torque until all fourteen bolts are started and the subframe is on its marks. One bolt torqued early locks the subframe in the wrong place and you'll be doing this again after the alignment shop calls."}, {"t": "torque", "label": "Steering rack bolts (M10)", "nm": 50, "c": {"level": "varies", "n": 2, "note": "Manufacturer 50 Nm + 90°; owner table 37 lb-ft + 45°. Same base value."}, "note": "+90° turn"}, {"t": "torque", "label": "Sway bar bracket bolts (M8)", "nm": 20, "c": {"level": "varies", "n": 2, "note": "Manufacturer 20 Nm + 90°; owner table 15 lb-ft + 45°."}, "note": "+90° turn"}, {"t": "torque", "label": "Pendulum mount bolts", "nm": 40, "alt": [50], "c": {"level": "medium", "n": 2, "note": "40 Nm for 8.8-grade bolts, 50 Nm for 10.9-grade, each + 90°. Check the number stamped on the bolt head."}, "note": "+90° turn"}, {"t": "ill", "id": "fsb-bolts", "cap": "Order matters: seat the rack, start everything loose, align to your marks, then torque. Subframe and arm bolts get their angle last."}]}, {"n": 13, "title": "Reconnect the rest", "blocks": [{"t": "text", "b": "Exhaust hanger back on the subframe. Ball joints: three nuts each side, 60 Nm for a cast arm or 100 Nm for an aluminium/sheet-steel arm. Tie rods: 20 Nm + 90°. Level sensor arm and plug.", "only": ["full"]}, {"t": "text", "b": "Exhaust hanger back on the subframe. Level sensor arm and plug.", "only": ["partial"]}, {"t": "text", "b": "Steering shaft: seat the u-joint back on the rack and torque the new bolt to 30 Nm. Only now may the wheel turn.", "only": ["full"]}]}, {"n": 14, "title": "End links, on the ground", "blocks": [{"t": "text", "b": "Pass the studs through the bar's holes (adjustable bars: start on the softer, outer hole), start new self-locking nuts. Wheels on, torque to 120 Nm, lower the car. Then torque the end-link nuts with the car on its wheels so the links aren't preloaded."}, {"t": "torque", "label": "End-link nuts (M10)", "nm": 65, "c": {"level": "high", "n": 3, "note": "65 Nm / 48 lb-ft agrees across the manufacturer guide, an MQB guide and a forum torque thread."}}]}, {"n": 15, "title": "Alignment, then re-check", "blocks": [{"t": "text", "b": "Drive gently to the alignment shop. Tell them the subframe was lowered. After 50 miles, re-check the end links and that nothing clunks over one-wheel bumps."}]}], "alsoReplace": [{"name": "Pendulum (dogbone) mount insert or bushing", "why": "It's unbolted anyway, and a tired one is the usual source of drivetrain clunk on these cars. A poly insert is $30 and ten minutes here versus an hour on its own."}, {"name": "Front sway-bar end links", "why": "They're off. If the boots are cracked or the joints have play, new ones now save a second trip under the car."}, {"name": "Subframe alignment (Deadset-style) kit", "why": "Replaces the subframe's slop with locating sleeves so it can't shift under load. Only sensible while the bolts are already out."}], "check": {"tab": "Pick a setting", "title": "Which hole, if your bar is adjustable?", "illId": "setting", "illCap": "Same logic as the rear bar: the hole closer to the pivot is stiffer.", "rows": [{"see": "Street car, all-season or touring tires", "means": "You want the roll reduction without changing balance much.", "do": "Softer (outer) hole. Most stay here."}, {"see": "Summer tires, already on the stiff rear setting", "means": "The car may have gone tail-happy; the front bar brings balance back.", "do": "Softer hole first, evaluate, then stiffer if the front still rolls more than the rear."}, {"see": "Track use", "means": "You'll tune front and rear together per event.", "do": "Stiffer hole, adjustable end links front and rear."}], "c": {"level": "community", "n": 3, "note": "Forum consensus plus one magazine test (fastest lap on the soft setting)."}}, "aftercare": ["Alignment within the first drive or two. Not optional.", "Re-torque end links after 50 miles.", "Poly bushings squeak when dry; re-grease at the first squeak.", "Clunk from the front on take-off after this job: check the pendulum mount bolts."], "disagreements": [{"topic": "Full drop or partial lower?", "pos": "Manufacturer disconnects steering column, ball joints and tie rods and drops the subframe fully; owners lower it about four inches and unbolt the rack.", "call": "Both work. Partial for a driveway, full on a lift. You choose at the top of the guide."}, {"topic": "+45° or +90° on the stretch bolts?", "pos": "Manufacturer PDF says +90°; the 2008 owner table says +45° on the same base values.", "call": "Manufacturer, since it's current and cites the bolt sizes. The base torque agrees everywhere."}, {"topic": "How hard is it?", "pos": "'Skill Level 1 – Easy' vs. every owner account.", "call": "4 out of 5. Plan a full afternoon and a helper."}, {"topic": "Load on the wheels during install?", "pos": "APR's sheet said keep the car loaded throughout; owners found the subframe wouldn't align that way.", "call": "Unloaded for the subframe and rack; loaded only for the final end-link torque."}], "sources": ["ECS Tuning Mk5/Mk6 Front Sway Bar installation PDF (2019)", "VWVortex 'DIY: Front Sway Bar Install' (2008)", "MyFastGTI 'MK5 Front Swaybar DIY' (2008)", "Pelican Parts front sway bar bushings article", "GolfMKV APR install troubleshooting thread (2013)", "Golfmk6 install threads (2014, 2015)", "Grassroots Motorsports 034 front bar test (2023)"], "embeds": [], "heroId": "fsb-drop"}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('endlinks',$j${"id": "endlinks", "title": "Sway bar end links", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "alsoFits": "2006–09 GTI/Rabbit · 05–10 Jetta · 06–08 A3 · Mk6 GTI/Golf", "category": "Suspension", "kind": "repair", "variants": {"question": "Front or rear?", "hint": "Front links run from the sway bar up to a bracket on the strut. Rear links run from the bar down to the trailing arm. Same technique, different sizes and torque.", "options": [{"id": "front", "label": "Front end links", "when": "18mm nut, 6mm triple-square"}, {"id": "rear", "label": "Rear end links", "when": "16mm nut, 6mm triple-square"}]}, "glance": {"timeFirst": "45 min", "timeRepeat": "20 min", "difficulty": 1.5, "cost": "$30–120 a pair", "risk": "Car on stands · seized nuts", "why": "End links are the two little rods that connect the sway bar to the suspension. When their ball joints wear, the bar rattles instead of working, and you hear it as a clunk over every manhole cover.", "note": "Four sources, all under an hour. Seized nuts are the only variable."}, "heroCap": "Front link: bar to strut bracket. Rear link: bar to trailing arm. Each end has a stud with a socket in its tip so you can hold it while the nut turns.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Front links: commonly loose or rattling past 80,000–120,000 miles", "only": ["front"]}, {"text": "Rear links: often still fine past 100,000; check whenever the bar is off", "only": ["rear"]}], "earliest": "Sooner on cars with stiffer aftermarket bars, which load the joints harder", "detail": "The symptom is a hollow clunk or rattle from one corner over small bumps, worst at low speed. Grab the link with the car on stands and wiggle: any play in the joint, or a torn boot, and it's done.", "factors": ["Aftermarket sway bar", "Lowered car (links at an angle)", "Salt-belt corrosion"], "inspect": ["Check whenever you're under the car with a wheel off"], "confidence": {"level": "community", "n": 4, "note": "Owner reports and vendor notes; no factory interval. Mileage is anecdotal."}}, "should": {"yesIf": ["Clunk or rattle from a corner over small bumps", "Visible play when you wiggle the link by hand", "Torn or missing rubber boot on a joint", "You just fitted a stiffer bar and the old links have miles on them"], "codes": [], "notes": ["Both sides. If one has worn, the other is close, and a mismatched pair loads the bar unevenly."], "confidence": {"level": "high", "n": 4, "note": "Symptoms and technique agree across vendor articles and forum threads."}}, "parts": [{"tier": "oe", "name": "Front end link, Genuine/OEM (each)", "pn": "Lemförder, TRW or Meyle HD", "note": "Lemförder is the OE maker", "price": "$25–45", "links": [], "only": ["front"]}, {"tier": "oe", "name": "Rear end link, Genuine/OEM (each)", "pn": "Lemförder or Meyle HD", "note": "", "price": "$20–35", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Self-locking nuts (×4)", "pn": "factory", "note": "Replace every time they come off", "price": "$6", "links": []}], "aftermarket": [{"name": "Adjustable end links (034, Whiteline, SuperPro)", "note": "Let you set the length so the bar sits unloaded at rest, which matters once the car is lowered or the bar is on its stiff setting. Heim-joint types are noisier and want greasing.", "price": "$120–250 a pair", "signal": "Worth it if lowered", "links": []}, {"name": "Moog / heavy-duty fixed links", "note": "Bigger joints than OE at OE length. A common, cheap answer to a rattle on a stock-height car.", "price": "$40–70 a pair", "signal": "Budget pick", "links": []}], "tools": [{"name": "Jack + two stands; 17mm for the lug bolts"}, {"name": "18mm wrench (ratcheting open-end is ideal) and a 6mm triple-square bit", "only": ["front"]}, {"name": "16mm wrench and a 6mm triple-square bit", "only": ["rear"]}, {"name": "Penetrating oil, wire brush, torque wrench to 65 Nm"}], "before": ["Raise both sides of that axle together. One wheel up loads the bar and the links won't come off without a fight.", "Soak the nuts with penetrating oil while you get the wheels off.", "Final torque happens with the car back on its wheels."], "steps": [{"n": 1, "title": "Raise the axle, wheels off", "blocks": [{"t": "text", "b": "Loosen lugs on the ground, raise both sides of the axle, stands under the body, wheels off."}]}, {"n": 2, "title": "Find the link", "blocks": [{"t": "text", "b": "Behind the strut, a short rod from the end of the sway bar up to a bracket on the strut body. Two nuts: one at the bar, one at the strut.", "only": ["front"]}, {"t": "text", "b": "Inboard of the wheel, a short rod from the end of the sway bar down to the trailing arm. Two nuts: one at the bar, one at the arm.", "only": ["rear"]}, {"t": "ill", "id": "fsb-endlink", "cap": "Triple-square in the stud's tip to hold it still; wrench on the nut does the turning."}]}, {"n": 3, "title": "Remove the nuts", "blocks": [{"t": "text", "b": "18mm on the nut. If the whole stud spins, put the 6mm triple-square into the socket in the stud's tip and hold it while you turn the nut. Work a seized nut back and forth rather than forcing it, and re-oil. No heat; the boot won't survive it.", "only": ["front"]}, {"t": "text", "b": "16mm on the nut, 6mm triple-square holding the stud if it spins. Work a seized nut back and forth and re-oil. No heat.", "only": ["rear"]}, {"t": "note", "b": "The bar isn't under load with both wheels up. Nothing springs when the link comes off."}]}, {"n": 4, "title": "Swap the link", "blocks": [{"t": "text", "b": "Pull the old link out, compare lengths with the new one, and fit the new one the same way round. Start new self-locking nuts by hand at both ends. Snug only."}]}, {"n": 5, "title": "Other side", "blocks": [{"t": "text", "b": "Repeat. Both sides, always."}]}, {"n": 6, "title": "Wheels on, car down, then torque", "blocks": [{"t": "text", "b": "Wheels on (120 Nm), lower the car, roll it a foot to settle. Then torque the link nuts with the weight on the wheels so the joints aren't clamped at a strange angle."}, {"t": "torque", "label": "Front end-link nuts", "nm": 65, "c": {"level": "high", "n": 3, "note": "65 Nm / 48 lb-ft: manufacturer guide, MQB guide, forum torque thread."}, "only": ["front"]}, {"t": "torque", "label": "Rear end-link nuts", "nm": 45, "c": {"level": "single", "n": 1, "note": "Factory manual value via a forum thread. Kit hardware may specify less; follow the kit."}, "only": ["rear"]}]}], "alsoReplace": [{"name": "Sway bar bushings", "why": "Rear bushings are two bolts away once the links are off. Front bushings can be swapped without dropping the subframe (Pelican confirms), and a dry rubber bushing is the other source of front-end squeak."}], "check": {"tab": "Is it the link?", "title": "Is the noise really the end link?", "illId": "fsb-endlink", "illCap": "Wiggle test: any play here, or a torn boot, is a bad link.", "rows": [{"see": "Hollow clunk over small bumps, one corner, low speed", "means": "Classic end link. Confirm with the wiggle test.", "do": "Replace both links on that axle."}, {"see": "Creak or groan when turning into a driveway", "means": "More likely the sway bar bushings or a strut top mount.", "do": "Check bushings first; they're cheaper."}, {"see": "Knock on acceleration or gear change", "means": "Drivetrain mount, usually the pendulum (dogbone) mount.", "do": "Different job; see the front sway bar guide's 'while you're in there'."}], "c": {"level": "community", "n": 3, "note": "Forum diagnosis threads plus vendor articles."}}, "aftercare": ["Re-check torque after 50 miles.", "If a new link rattles immediately, the nut was torqued in the air or the link length is wrong for a lowered car."], "disagreements": [{"topic": "Which bit holds the stud?", "pos": "6mm triple-square (most sources), 5mm hex (ECS's own links), '16mm triple-square' (Pelican, clearly a typo).", "call": "6mm triple-square for factory links; check your new links' studs."}, {"topic": "Torque in the air or on the ground?", "pos": "Vendor guides torque on the lift; the factory manual says curb weight.", "call": "On the ground."}, {"topic": "Front torque", "pos": "65 Nm (PQ35/MQB sources) vs 90 Nm (a 2005 thread).", "call": "65. The 90 Nm figure is Mk4."}], "sources": ["ECS Tuning front sway bar PDF", "VWVortex 'Sway Bar Link Replacement?' (2016)", "Pelican Parts drop-link article", "1A Auto Mk5/6 end-link video guide", "IE and Eco-de Tuning MQB guides (technique only)", "TDIClub Bentley torque thread"], "embeds": [], "heroId": "fsb-endlink"}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('air-filter-oe',$j${"id": "air-filter-oe", "title": "Engine air filter (stock airbox)", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "alsoFits": "2006–09 GTI · 05–08 Jetta 2.0T · 07+ Eos (engine-cover airbox)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "20 min", "timeRepeat": "10 min", "difficulty": 1, "cost": "$15–30", "risk": "None worth mentioning", "why": "On this engine the air filter lives inside the engine cover. It's the cheapest, easiest piece of maintenance on the car, and it's also the first thing to check if you've just bought it: previous owners forget this one for years.", "note": "Two vendor write-ups and a forum thread agree on everything except the screwdriver bit."}, "heroCap": "The engine cover is the airbox. Air comes in through the snorkel at the front-left, through the filter inside the cover, and out the back to the turbo inlet pipe.", "lifespan": {"title": "When to expect it", "headline": ["Inspect yearly; owners replace around every 20,000–40,000 miles"], "earliest": null, "detail": "A paper filter fails gradually. Hold it up to the light: if you can't see light through the pleats, or there's grit and leaves in the airbox, change it. Dusty roads and a lot of highway bugs shorten it.", "factors": ["Dusty or gravel roads", "Unknown history", "Rodent activity in the engine bay (check the snorkel)"], "inspect": ["Every oil change: pull the cover and look. It's two screws."], "confidence": {"level": "single", "n": 1, "note": "Factory interval not confirmed in this pass. Owner practice and vendor advice only."}}, "should": {"yesIf": ["You don't know when it was last done", "Filter looks grey, or you can't see light through it", "Debris in the airbox", "Every year or so regardless"], "codes": [], "notes": ["Stock paper filter versus an oiled cotton cone: the forums are clear that the stock box pulls cool air from the grille and the paper element isn't a restriction on a stock or Stage 1 car. Oiled filters can also foul the mass-airflow sensor. Stay paper unless you're going to a full intake (that's a separate guide)."], "confidence": {"level": "high", "n": 3, "note": "Vendor write-ups and forum consensus agree."}}, "parts": [{"tier": "oe", "name": "Engine air filter, Genuine VW", "pn": "1F0 129 620 (confirm against your VIN)", "note": "Paper element for the engine-cover airbox", "price": "$25–35", "links": []}, {"tier": "oem", "name": "Engine air filter, Mann or Mahle", "pn": "Mann C 35 154 (confirm)", "note": "Same filter, maker's box", "price": "$12–20", "links": []}], "aftermarket": [{"name": "Drop-in cotton panel (K&N, aFe)", "note": "Fits the stock box. Slight airflow gain on paper, real risk of oil on the MAF sensor if over-oiled, and no cold-air benefit. Forums are lukewarm.", "price": "$50–70", "signal": "Community verdict: stay paper", "links": []}], "tools": [{"name": "T20 or T25 Torx (check your snorkel screws)"}, {"name": "Phillips screwdriver"}, {"name": "Pliers for the hose clamp; shop vac or rag for the box"}], "before": ["Engine off and cool enough to lean over.", "Have the new filter out of the box so you can compare it to the old one."], "steps": [{"n": 1, "title": "Free the snorkel", "blocks": [{"t": "text", "b": "Front-left of the engine bay, the intake snorkel joins the engine cover. Remove the two Torx screws (T20 on most cars, T25 on some) and, if there's a hose clamp, squeeze it off with pliers."}]}, {"n": 2, "title": "Unplug the MAF, unlock the inlet pipe", "blocks": [{"t": "text", "b": "Unplug the mass-airflow sensor connector on the cover's outlet. Flip the two clips holding the turbo inlet pipe to the cover with a flat screwdriver and pull the pipe off. Some people skip this and tilt the cover; unplugging it costs ten seconds and protects the connector."}]}, {"n": 3, "title": "Lift the cover", "blocks": [{"t": "text", "b": "Grab the cover at all four corners, wiggle, and pull straight up. It sits on four rubber grommets; some will come up with it, some stay on the studs. Set them aside so they don't end up in the belt."}, {"t": "ill", "id": "airbox", "cap": "Four grommets, two snorkel screws, two inlet clips. That's all that holds it."}]}, {"n": 4, "title": "Open the box", "blocks": [{"t": "text", "b": "Turn the cover over. Eight Phillips screws around the edge hold the two halves together. Separate them and lift out the filter."}]}, {"n": 5, "title": "Clean and swap", "blocks": [{"t": "text", "b": "Vacuum or wipe the inside of both halves; leaves and grit collect on the intake side. Fit the new filter the same way round as the old one (seal edge into the groove), close the halves, and put the eight screws back snug. Don't crank them; it's plastic."}]}, {"n": 6, "title": "Cover back on", "blocks": [{"t": "text", "b": "Grommets onto the studs, cover pressed down at all four corners until it clicks, inlet pipe on and clips locked, MAF plugged in, snorkel screws and clamp back on. Start it and listen for hiss at the inlet pipe; a whistle means a clip isn't locked."}]}], "alsoReplace": [{"name": "Cabin air filter", "why": "Same trip to the parts store, same 'nobody ever changed it' energy. It's behind the glovebox and takes ten minutes."}], "check": {"tab": "Read the filter", "title": "Reading your old filter", "illId": "airbox", "illCap": "Light through the pleats is the test.", "rows": [{"see": "Off-white, light passes through easily", "means": "Fine.", "do": "Put it back or replace if it's cheap and you're already here."}, {"see": "Grey, light passes with effort", "means": "Doing its job; near the end.", "do": "Replace."}, {"see": "Black, blocked, or debris/rodent nesting in the box", "means": "Restricting airflow; the previous owner never did this.", "do": "Replace, vacuum the box, check the snorkel and inlet pipe for debris."}], "c": {"level": "community", "n": 3, "note": "Standard practice; consistent across sources."}}, "aftercare": ["Note the mileage somewhere you'll find it.", "If you ever see oil residue on the MAF sensor after switching to an oiled filter, clean it with MAF cleaner and go back to paper."], "disagreements": [{"topic": "T20 or T25?", "pos": "Pelican says T20, FCP Euro says T25.", "call": "Bring both."}, {"topic": "Unplug the MAF?", "pos": "Pelican doesn't; FCP Euro does.", "call": "Unplug it."}], "sources": ["Pelican Parts Mk5 GTI Air Filter Replacement", "FCP Euro Mk5 GTI engine cover removal (oil filter housing article)", "VWVortex engine-cover / intake thread", "DAP Mk5 GTI service schedule article"], "embeds": [], "heroId": "airbox-bay"}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
